    if(!allowTeamChanges){msg.textContent='Team creation and joining are currently closed. Your existing teams and invite codes remain available.';['#createTeamForm','#joinTeamForm'].forEach(selector=>$(selector).querySelectorAll('input,button').forEach(el=>el.disabled=true));}
    const draw=async()=>{try{const teams=await window.VYUHAM_API.get('/teams/me');if(allowTeamChanges)msg.textContent=teams.length?`${teams.length} team${teams.length===1?'':'s'} linked to your profile.`:'No teams yet. Create one or join using an invite code.';cards.innerHTML=teams.map(t=>`<article class="info-card team-card"><span class="num">${t.created_by===profile.id?'TEAM LEAD':'TEAM MEMBER'} / ${esc(t.invite_code)}</span><h3>${esc(t.name)}</h3><p>${Number(t.member_count)||1} member${Number(t.member_count)===1?'':'s'} · Created ${esc(new Date(t.created_at).toLocaleDateString())}</p><button type="button" class="button button-outline copy-team-code" data-code="${esc(t.invite_code)}">COPY INVITE CODE</button><details class="team-roster" data-team-id="${esc(t.id)}"><summary>VIEW TEAM ROSTER</summary><div class="team-roster-list muted">Open to load current members.</div></details></article>`).join('')||'<div class="empty-state" style="grid-column:1/-1">No teams are linked to this participant account yet.</div>'}catch(error){msg.textContent=`Could not load teams: ${error.message}`;}};
    await draw();
    $('#createTeamForm').addEventListener('submit',async e=>{e.preventDefault();if(!allowTeamChanges){toast('Team creation is currently closed.');return}const button=e.currentTarget.querySelector('button');button.disabled=true;try{const team=await window.VYUHAM_API.post('/teams',{name:new FormData(e.currentTarget).get('name').trim()});toast(`Team ${team.name} created. You are the team lead. Share invite code ${team.invite_code} with your teammates.`);e.currentTarget.reset();await draw()}catch(error){toast(`Team could not be created: ${error.message}`)}finally{button.disabled=false}});
