    cards.addEventListener('toggle',async e=>{const roster=e.target.closest('.team-roster');if(!roster||!roster.open||roster.dataset.loaded)return;const root=roster.querySelector('.team-roster-list');root.textContent='Loading team roster…';try{const team=await window.VYUHAM_API.get(`/teams/${encodeURIComponent(roster.dataset.teamId)}`);root.innerHTML=team.members.map(member=>`<div class="team-member"><span>${esc(member.name||'Participant')}</span><small>${esc(new Date(member.joined_at).toLocaleDateString())}</small></div>`).join('')||'No members found.';roster.dataset.loaded='true'}catch(error){root.textContent=`Could not load roster: ${error.message}`}},true);
